void Solver::bump_var(int var, double coeff) {
    // Increment activity with the current increment and coefficient
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Lazy rescaling: only rescale when a single variable exceeds a high threshold
    // This reduces the frequency of the O(vars) loop.
    const double HIGH_THRESHOLD = 1e120; // higher than original 1e100
    if (activity[var] > HIGH_THRESHOLD) {
        // Scale down all activities and the increment to avoid overflow.
        const double SCALE_FACTOR = 1e-120;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= SCALE_FACTOR;
        }
        var_inc *= SCALE_FACTOR;
    }

    // Keep the VSIDS heap up‑to‑date.
    // If the variable is already in the heap, update its position;
    // otherwise insert it (this can happen after backtrack).
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
